#include <cassert>
#include <climits>
#include <string>
#include <unordered_set>

struct RewardModel {
    int coins;
    bool ownsBlade;
    std::unordered_set<std::string> appliedEvents;
    RewardModel() : coins(0), ownsBlade(false) {}

    bool Earn(const std::string& eventId, int amount) {
        if (eventId.empty() || amount <= 0 ||
            appliedEvents.count(eventId) != 0 || amount > INT_MAX - coins)
            return false;
        coins += amount;
        appliedEvents.insert(eventId);
        return true;
    }
    int Missing(int price) const {
        return coins >= price ? 0 : price - coins;
    }
    int Percent(int price) const {
        if (price <= 0) return 100;
        const int capped = coins >= price ? price : coins;
        return static_cast<int>(100LL * capped / price);
    }
    bool PurchaseBlade(int price) {
        if (price <= 0 || ownsBlade || coins < price) return false;
        coins -= price;
        ownsBlade = true;
        return true;
    }
};

int main() {
    RewardModel m;
    assert(m.Missing(100) == 100 && m.Percent(100) == 0);
    assert(m.Earn("enemy-001", 35));
    assert(!m.Earn("enemy-001", 35)); // 재전송 보상 방지
    assert(m.Missing(100) == 65 && m.Percent(100) == 35);
    assert(!m.PurchaseBlade(100));
    assert(m.Earn("quest-002", 70));
    assert(m.Percent(100) == 100 && m.Missing(100) == 0);
    assert(m.PurchaseBlade(100) && m.coins == 5);
    assert(!m.PurchaseBlade(100));
    assert(!m.Earn("bad", -1));
}
